from pathlib import Path
p=Path('/home/ubuntu/hofong-portfolio/client/src/index.css')
s=p.read_text()
if '.portfolio-grid-override' not in s:
    s += '''\n/* portfolio-grid-override: equal cards instead of the previous featured-card layout */\n.project-list { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 42px 20px; align-items: start; }\n.project-list .project-card, .project-list .project-card:nth-child(3n) { grid-column: auto; display: block; }\n.project-list .project-card .project-media, .project-list .project-card:nth-child(3n) .project-media { aspect-ratio: 1.18; }\n.project-list .project-info h3 { font-size: clamp(19px, 2vw, 25px); margin-top: 12px; }\n.certificate-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }\n.certificate-card { padding: 16px; }\n.certificate-image-button { width: calc(100% + 32px); margin: -16px -16px 16px; }\n.certificate-card h3 { font-size: 18px; margin: 10px 0 7px; }\n.certificate-card p { font-size: 12px; line-height: 1.6; }\n.certificate-meta { gap: 8px; margin-top: 14px; }\n@media (max-width: 850px) { .project-list { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 36px 16px; } .project-list .project-card .project-media, .project-list .project-card:nth-child(3n) .project-media { aspect-ratio: 1.1; } .certificate-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }\n@media (max-width: 540px) { .project-list { grid-template-columns: 1fr; gap: 42px; } .certificate-grid { grid-template-columns: 1fr; } }\n'''
p.write_text(s)
